 package clinic;

 import java.io.File;
 import java.nio.file.Files;

 public class ArchiveService {
     private final File root;

     public ArchiveService(File root) {
         this.root = root;
     }

+    public String archive(PatientCard card) throws Exception {
+        File folder = new File(root, card.year());
+        folder.mkdirs();
+
+        File target = new File(folder, card.id() + ".json");
+        Files.writeString(target.toPath(), card.toJson());
+
+        return target.getName();
+    }
 }
